        Path input=resolved(root,active.getString("inputPng")),returned=resolved(root,request.getString("returnedPath"));if(!hash(input).equals(active.getString("inputSha256"))||!active.getString("inputSha256").equals(request.getString("inputSha256"))||!hash(returned).equals(request.getString("outputSha256")))throw new Exception("真实请求输入/返回SHA不匹配");
        for(String field:new String[]{"width","height"})if(active.getInt(field)!=request.getInt(field))throw new Exception("请求尺寸不匹配");for(String field:new String[]{"targetBoxes","protectedBoxes"})if(!active.getJSONArray(field).toString().equals(request.getJSONArray(field).toString()))throw new Exception("请求目标或保护框不匹配");
        int w=active.getInt("width"),h=active.getInt("height");int[] sourceCrop=ints(active.getJSONArray("sourceCrop"));if(sourceCrop[2]-sourceCrop[0]!=w||sourceCrop[3]-sourceCrop[1]!=h)throw new Exception("源图裁切尺寸不匹配");int[][] targets=boxes(active.getJSONArray("targetBoxes")),protections=boxes(active.getJSONArray("protectedBoxes"));ImageCleanup.prompt(w,h,targets,protections);report.put("processingStage","returned_size_decode");BufferedImage decoded=ImageIO.read(returned.toFile());if(decoded==null)throw new Exception("模型图像无法解码");ImageCleanup.validateReturnedSize(decoded.getWidth(),decoded.getHeight(),w,h);
