            for(int i=0;i<plan.points.length;i++){float x=plan.cellLeft(i),y=plan.cellTop(i);JSONArray cell=new JSONArray(new float[]{x,y,x+cellStep(plan,i),y+cellStep(plan,i)});cells.put(cell);for(int protectedIndex=0;protectedIndex<protections.length;protectedIndex++){int[] protect=protections[protectedIndex];if(x<protect[2]+2&&x+cellStep(plan,i)>protect[0]-2&&y<protect[3]+2&&y+cellStep(plan,i)>protect[1]-2){JSONObject conflict=new JSONObject().put("member",member.getString("id")).put("glyphIndex",i).put("cell",cell).put("protectedBoxIndex",protectedIndex).put("protectedBox",new JSONArray(protect));report.put("layoutConflict",conflict);throw new Exception("成员字格覆盖保护框："+conflict);}}for(int j=0;j<targets.length;j++)if(j!=index){int[] other=targets[j];if(x<other[2]+2&&x+cellStep(plan,i)>other[0]-2&&y<other[3]+2&&y+cellStep(plan,i)>other[1]-2){JSONObject conflict=new JSONObject().put("member",member.getString("id")).put("otherMember",memberList.getJSONObject(j).getString("id")).put("glyphIndex",i).put("cell",cell).put("otherTarget",new JSONArray(other));report.put("layoutConflict",conflict);throw new Exception("组内两个目标字格冲突："+conflict);}}}
