    static void writeBoundaryControl(Path root,BufferedImage original,JSONObject member)throws Exception{
        int[] b=ints(member.getJSONArray("absoluteBox"));Path dir=root.resolve("逐处").resolve(member.getString("id"));
        int[] context={Math.max(0,b[0]-12),Math.max(0,b[1]-12),Math.min(original.getWidth(),b[2]+12),Math.min(original.getHeight(),b[3]+12)};BufferedImage boundary=crop(original,context);Graphics2D g=boundary.createGraphics();g.setStroke(new BasicStroke(1));g.setColor(Color.RED);g.drawRect(b[0]-context[0],b[1]-context[1],b[2]-b[0]-1,b[3]-b[1]-1);if(b[2]-b[0]>4&&b[3]-b[1]>4){g.setColor(Color.CYAN);g.drawRect(b[0]-context[0]+2,b[1]-context[1]+2,b[2]-b[0]-5,b[3]-b[1]-5);}g.dispose();writeImage(boundary,dir.resolve("原图_目标边界与2px内缘.png"));boundary.flush();
        member.put("targetBoundaryControlFile",relative(root,dir.resolve("原图_目标边界与2px内缘.png"))).put("boundaryContext",new JSONArray(context)).put("boundaryControlLegend","Red: target extent; cyan: boundary after 2-pixel inset. Visual check required for source strokes cut by these boundaries.");
    }
